// Mini hava istasyonu: DHT22 ile ölç, OLED'de göster.
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

const int DHT_PIN = 4;
const int SDA_PIN = 21;
const int SCL_PIN = 22;

DHT dht(DHT_PIN, DHT22);
Adafruit_SSD1306 ekran(128, 64, &Wire, -1);

void setup() {
  Serial.begin(115200);
  dht.begin();
  Wire.begin(SDA_PIN, SCL_PIN);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED bulunamadi. Kablolari ve 0x3C adresini kontrol et.");
    while (true) delay(1000);
  }
  ekran.setTextColor(SSD1306_WHITE);
}

void loop() {
  float sicaklik = dht.readTemperature();
  float nem = dht.readHumidity();

  ekran.clearDisplay();
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.println("Hava istasyonu");

  if (isnan(sicaklik) || isnan(nem)) {
    ekran.println();
    ekran.println("Sensor okunamadi.");
    Serial.println("DHT22 okunamadi.");
  } else {
    ekran.setTextSize(2);
    ekran.setCursor(0, 20);
    ekran.print(sicaklik, 1);
    ekran.println(" C");
    ekran.setCursor(0, 44);
    ekran.print(nem, 0);
    ekran.println(" %");
    Serial.printf("Sicaklik: %.1f C  Nem: %.0f %%\n", sicaklik, nem);
  }
  ekran.display();
  delay(2000);
}
